package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DateRec struct {
	DtId   string
	DtYyyy int64
	DtMm   int64
	DtDd   int64
}

var WsEofFlag string = "N"
var WsLeapFlag string = "N"
var WsQ int64 = 0
var WsR4 int64 = 0
var WsR100 int64 = 0
var WsR400 int64 = 0
var WsMaxDay int64 = 0
var WsValid int64 = 0
var WsBadMonth int64 = 0
var WsBadDay int64 = 0

var DateRecVar DateRec

var dateFile *os.File
var dateReader *bufio.Reader
var inputDone bool

func isInputDone() bool { return WsEofFlag == "Y" }
func isLeap() bool      { return WsLeapFlag == "Y" }

func truncateInt64(v int64, digits int) int64 {
	if digits <= 0 {
		return 0
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	v = v % mod
	if v < 0 {
		v += mod
	}
	return v
}

func storePic99(v int64) int64 {
	return truncateInt64(v, 2)
}
func storePic9_4(v int64) int64 {
	return truncateInt64(v, 4)
}
func storePic9_3(v int64) int64 {
	return truncateInt64(v, 3)
}

func formatPic9(v int64, width int) string {
	// zero padded, truncated already
	if width <= 0 {
		return ""
	}
	s := strconv.FormatInt(v, 10)
	// v is non-negative due to truncation, but handle negative just in case
	if len(s) > width {
		s = s[len(s)-width:]
	} else if len(s) < width {
		s = strings.Repeat("0", width-len(s)) + s
	}
	return s
}

func formatX(s string, width int) string {
	if len(s) > width {
		return s[:width]
	}
	if len(s) < width {
		return s + strings.Repeat(" ", width-len(s))
	}
	return s
}

func parseDateRec(line string) DateRec {
	// pad to 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	var r DateRec
	r.DtId = line[0:4]
	r.DtYyyy = parseIntField(line, 4, 4)
	r.DtMm = parseIntField(line, 8, 2)
	r.DtDd = parseIntField(line, 10, 2)
	return r
}

func parseIntField(line string, off, wid int) int64 {
	s := line[off : off+wid]
	s = strings.TrimSpace(s)
	if s == "" {
		return 0
	}
	// COBOL numeric fields may contain spaces? But treat non-digit as 0?
	// Filter: if contains non-digit, try to parse digits only?
	// The spec says digits only; we'll parse as integer if possible
	v, err := strconv.ParseInt(s, 10, 64)
	if err != nil {
		// if parsing fails, treat as 0 (e.g., spaces)
		// try to extract digits
		digits := ""
		for _, ch := range s {
			if ch >= '0' && ch <= '9' {
				digits += string(ch)
			}
		}
		if digits == "" {
			return 0
		}
		v, _ = strconv.ParseInt(digits, 10, 64)
		return v
	}
	return v
}

// prevent unused import error for decimal
var _ = decimal.NewFromInt

func MAINPARA() {
	// OPEN INPUT DATE-FILE
	var err error
	dateFile, err = os.Open("input.dat")
	if err != nil {
		// if file doesn't exist, treat as empty (COBOL would error, but we handle)
		dateFile = nil
		dateReader = nil
		WsEofFlag = "Y"
	} else {
		dateReader = bufio.NewReader(dateFile)
	}
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	if dateFile != nil {
		dateFile.Close()
	}
	// DISPLAY "VALID: " WS-VALID " BAD MONTH: " WS-BAD-MONTH " BAD DAY: " WS-BAD-DAY
	fmt.Printf("VALID: %s BAD MONTH: %s BAD DAY: %s\n",
		formatPic9(WsValid, 2),
		formatPic9(WsBadMonth, 2),
		formatPic9(WsBadDay, 2),
	)
}

func READPARA() {
	if dateReader == nil {
		WsEofFlag = "Y"
		return
	}
	line, err := dateReader.ReadString('\n')
	if err != nil {
		// EOF
		// check if we got a line before EOF
		if len(line) > 0 {
			// process this last line without newline
			if strings.HasSuffix(line, "\n") {
				line = strings.TrimSuffix(line, "\n")
				line = strings.TrimSuffix(line, "\r")
			}
			DateRecVar = parseDateRec(line)
			return
		}
		WsEofFlag = "Y"
		return
	}
	// strip newline
	line = strings.TrimSuffix(line, "\n")
	line = strings.TrimSuffix(line, "\r")
	DateRecVar = parseDateRec(line)
}

func PROCESSPARA() {
	LEAPPARA()
	if DateRecVar.DtMm < 1 || DateRecVar.DtMm > 12 {
		WsBadMonth = storePic99(WsBadMonth + 1)
		fmt.Printf("%s BAD MONTH %s\n", formatX(DateRecVar.DtId, 4), formatPic9(DateRecVar.DtMm, 2))
	} else {
		DAYSPARA()
		if DateRecVar.DtDd < 1 || DateRecVar.DtDd > WsMaxDay {
			WsBadDay = storePic99(WsBadDay + 1)
			fmt.Printf("%s BAD DAY %s MAX %s\n", formatX(DateRecVar.DtId, 4), formatPic9(DateRecVar.DtDd, 2), formatPic9(WsMaxDay, 2))
		} else {
			WsValid = storePic99(WsValid + 1)
			fmt.Printf("%s VALID %s-%s-%s\n", formatX(DateRecVar.DtId, 4), formatPic9(DateRecVar.DtYyyy, 4), formatPic9(DateRecVar.DtMm, 2), formatPic9(DateRecVar.DtDd, 2))
		}
	}
	READPARA()
}

func LEAPPARA() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	WsQ = storePic9_4(DateRecVar.DtYyyy / 4)
	WsR4 = storePic9_3(DateRecVar.DtYyyy % 4)
	WsQ = storePic9_4(DateRecVar.DtYyyy / 100)
	WsR100 = storePic9_3(DateRecVar.DtYyyy % 100)
	WsQ = storePic9_4(DateRecVar.DtYyyy / 400)
	WsR400 = storePic9_3(DateRecVar.DtYyyy % 400)
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DAYSPARA() {
	switch DateRecVar.DtMm {
	case 2:
		if isLeap() {
			WsMaxDay = storePic99(29)
		} else {
			WsMaxDay = storePic99(28)
		}
	case 4, 6, 9, 11:
		WsMaxDay = storePic99(30)
	default:
		WsMaxDay = storePic99(31)
	}
}

func main() {
	MAINPARA()
}
